import urllib.request, json, base64, zlib, struct

def call_tool(name, args):
    url = "http://loophole-sim:8000/mcp"
    headers = {"Content-Type": "application/json", "Accept": "application/json, text/event-stream"}
    req = urllib.request.Request(url, data=json.dumps({
        "jsonrpc": "2.0", "id": 1, "method": "tools/call",
        "params": {"name": name, "arguments": args}
    }).encode(), headers=headers)
    with urllib.request.urlopen(req) as resp:
        return json.loads(resp.read().decode())

res = call_tool("render", {"view": "top"})
for item in res["result"]["content"]:
    if item["type"] == "text":
        print("TEXT:", item["text"])
    elif item["type"] == "image":
        raw = base64.b64decode(item["data"])
        w, h, bit_depth, color_type = struct.unpack(">IIBB", raw[16:26])
        print(f"PNG: {w}x{h}, depth={bit_depth}, color_type={color_type}, bytes={len(raw)}")
        open("/tmp/opencode/top.png", "wb").write(raw)
'

