// Save carved voxels if dilate_fg == 0
if (dilate_fg == 0) {
    FILE* fa = fopen("/tmp/opencode/ptsA.bin", "wb");
    uint32_t na = ptsA.size();
    fwrite(&na, 4, 1, fa);
    fwrite(ptsA.data(), sizeof(Vec3), na, fa);
    fclose(fa);

    FILE* fb = fopen("/tmp/opencode/ptsB.bin", "wb");
    uint32_t nb = ptsB.size();
    fwrite(&nb, 4, 1, fb);
    fwrite(ptsB.data(), sizeof(Vec3), nb, fb);
    fclose(fb);
}

