arguments.content:
#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <vector>
#include <algorithm>
#include <random>
#include <thread>
#include <mutex>
#include <atomic>
#include <chrono>

struct Vec3 {
    float x, y, z;
    Vec3 operator+(const Vec3& o) const { return {x + o.x, y + o.y, z + o.z}; }
    Vec3 operator-(const Vec3& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }
};

inline float dot(const Vec3& a, const Vec3& b) { return a.x*b.x + a.y*b.y + a.z*b.z; }
inline Vec3 cross(const Vec3& a, const Vec3& b) {
    return {a.y*b.z - a.z*b.y, a.z*b.x - a.x*b.z, a.x*b.y - a.y*b.x};
}
inline float norm(const Vec3& a) { return sqrtf(dot(a, a)); }

struct Quat { float w, x, y, z; };

inline Quat q_norm(const Quat& q) {
    float n = sqrtf(q.w*q.w + q.x*q.x + q.y*q.y + q.z*q.z);
    if (n < 1e-12f) return {1, 0, 0, 0};
    float inv = 1.0f / n;
    Quat r = {q.w*inv, q.x*inv, q.y*inv, q.z*inv};
    if (r.w < 0.0f) r = {-r.w, -r.x, -r.y, -r.z};
    return r;
}

inline Quat q_mul(const Quat& a, const Quat& b) {
    return {
        a.w*b.w - a.x*b.x - a.y*b.y - a.z*b.z,
        a.w*b.x + a.x*b.w + a.y*b.z - a.z*b.y,
        a.w*b.y - a.x*b.z + a.y*b.w + a.z*b.x,
        a.w*b.z + a.x*b.y - a.y*b.x + a.z*b.w
    };
}

inline Quat q_exp(const Vec3& w) {
    float th = norm(w);
    if (th < 1e-7f) return q_norm({1.0f, 0.5f*w.x, 0.5f*w.y, 0.5f*w.z});
    float s = sinf(0.5f * th) / th;
    return q_norm({cosf(0.5f * th), w.x * s, w.y * s, w.z * s});
}

inline float q_angle(const Quat& a, const Quat& b) {
    float d = fabsf(a.w*b.w + a.x*b.x + a.y*b.y + a.z*b.z);
    if (d >= 1.0f) return 0.0f;
    return 2.0f * acosf(d);
}

inline Quat q_slerp(const Quat& a, Quat b, float t) {
    float d = a.w*b.w + a.x*b.x + a.y*b.y + a.z*b.z;
    if (d < 0.0f) { d = -d; b = {-b.w, -b.x, -b.y, -b.z}; }
    if (d > 0.9995f) {
        return q_norm({a.w + t*(b.w - a.w), a.x + t*(b.x - a.x), a.y + t*(b.y - a.y), a.z + t*(b.z - a.z)});
    }
    float th0 = acosf(std::min(1.0f, d));
    float th = th0 * t;
    float s0 = cosf(th) - d * sinf(th) / sinf(th0);
    float s1 = sinf(th) / sinf(th0);
    return q_norm({s0*a.w + s1*b.w, s0*a.x + s1*b.x, s0*a.y + s1*b.y, s0*a.z + s1*b.z});
}

struct Mat3 {
    float m[9];
    inline Vec3 apply(const Vec3& v) const {
        return {
            m[0]*v.x + m[1]*v.y + m[2]*v.z,
            m[3]*v.x + m[4]*v.y + m[5]*v.z,
            m[6]*v.x + m[7]*v.y + m[8]*v.z
        };
    }
};

inline Mat3 q_to_mat(const Quat& q) {
    float xx = q.x*q.x, yy = q.y*q.y, zz = q.z*q.z;
    float xy = q.x*q.y, xz = q.x*q.z, yz = q.y*q.z;
    float wx = q.w*q.x, wy = q.w*q.y, wz = q.w*q.z;
    return {{
        1.0f - 2.0f*(yy + zz), 2.0f*(xy - wz),        2.0f*(xz + wy),
        2.0f*(xy + wz),        1.0f - 2.0f*(xx + zz), 2.0f*(yz - wx),
        2.0f*(xz - wy),        2.0f*(yz + wx),        1.0f - 2.0f*(xx + yy)
    }};
}

void edt_1d(const float* f, float* d, int n, int* v, float* z) {
    int k = 0; v[0] = 0; z[0] = -1e20f; z[1] = +1e20f;
    for (int q = 1; q < n; ++q) {
        float s;
        while (true) {
            int vk = v[k];
            s = ((f[q] + q*q) - (f[vk] + vk*vk)) / (2.0f * (q - vk));
            if (s <= z[k]) k--; else break;
        }
        k++; v[k] = q; z[k] = s; z[k + 1] = +1e20f;
    }
    k = 0;
    for (int q = 0; q < n; ++q) {
        while (z[k + 1] < q) k++;
        float dx = (float)(q - v[k]);
        d[q] = dx*dx + f[v[k]];
    }
}

void edt_3d(std::vector<float>& grid, int NX, int NY, int NZ) {
    int maxN = std::max({NX, NY, NZ});
    std::vector<float> f(maxN), d(maxN), z(maxN + 2);
    std::vector<int> v(maxN + 1);
    for (int iz = 0; iz < NZ; ++iz)
        for (int iy = 0; iy < NY; ++iy) {
            float* row = &grid[((size_t)iz * NY + iy) * NX];
            for (int ix = 0; ix < NX; ++ix) f[ix] = row[ix];
            edt_1d(f.data(), row, NX, v.data(), z.data());
        }
    for (int iz = 0; iz < NZ; ++iz)
        for (int ix = 0; ix < NX; ++ix) {
            for (int iy = 0; iy < NY; ++iy) f[iy] = grid[((size_t)iz * NY + iy) * NX + ix];
            edt_1d(f.data(), d.data(), NY, v.data(), z.data());
            for (int iy = 0; iy < NY; ++iy) grid[((size_t)iz * NY + iy) * NX + ix] = d[iy];
        }
    for (int iy = 0; iy < NY; ++iy)
        for (int ix = 0; ix < NX; ++ix) {
            for (int iz = 0; iz < NZ; ++iz) f[iz] = grid[((size_t)iz * NY + iy) * NX + ix];
            edt_1d(f.data(), d.data(), NZ, v.data(), z.data());
            for (int iz = 0; iz < NZ; ++iz) grid[((size_t)iz * NY + iy) * NX + ix] = d[iz];
        }
}

struct SDFGrid {
    float x0, y0, z0, h, inv_h;
    int NX, NY, NZ;
    Vec3 aabb_min, aabb_max;
    std::vector<int16_t> sdf_mm10;

    inline float query_outside(const Vec3& p) const {
        float dx = std::max({0.0f, aabb_min.x - p.x, p.x - aabb_max.x});
        float dy = std::max({0.0f, aabb_min.y - p.y, p.y - aabb_max.y});
        float dz = std::max({0.0f, aabb_min.z - p.z, p.z - aabb_max.z});
        return sqrtf(dx*dx + dy*dy + dz*dz);
    }

    inline float query_nearest(const Vec3& p) const {
        int ix = (int)floorf((p.x - x0) * inv_h);
        int iy = (int)floorf((p.y - y0) * inv_h);
        int iz = (int)floorf((p.z - z0) * inv_h);
        if ((unsigned)ix < (unsigned)NX && (unsigned)iy < (unsigned)NY && (unsigned)iz < (unsigned)NZ) {
            return sdf_mm10[((size_t)iz * NY + iy) * NX + ix] * 1e-4f;
        }
        return query_outside(p);
    }

    inline float query_trilinear(const Vec3& p) const {
        float gx = (p.x - x0) * inv_h - 0.5f;
        float gy = (p.y - y0) * inv_h - 0.5f;
        float gz = (p.z - z0) * inv_h - 0.5f;
        int ix = (int)floorf(gx), iy = (int)floorf(gy), iz = (int)floorf(gz);
        if (ix < 0 || ix + 1 >= NX || iy < 0 || iy + 1 >= NY || iz < 0 || iz + 1 >= NZ) {
            return query_outside(p);
        }
        float tx = gx - ix, ty = gy - iy, tz = gz - iz;
        size_t b00 = ((size_t)iz * NY + iy) * NX + ix;
        size_t b10 = b00 + NX;
        size_t b01 = b00 + (size_t)NY * NX;
        size_t b11 = b01 + NX;
        float c00 = sdf_mm10[b00] * (1.0f - tx) + sdf_mm10[b00 + 1] * tx;
        float c10 = sdf_mm10[b10] * (1.0f - tx) + sdf_mm10[b10 + 1] * tx;
        float c01 = sdf_mm10[b01] * (1.0f - tx) + sdf_mm10[b01 + 1] * tx;
        float c11 = sdf_mm10[b11] * (1.0f - tx) + sdf_mm10[b11 + 1] * tx;
        float c0 = c00 * (1.0f - ty) + c10 * ty;
        float c1 = c01 * (1.0f - ty) + c11 * ty;
        return (c0 * (1.0f - tz) + c1 * tz) * 1e-4f;
    }

    inline Vec3 grad(const Vec3& p) const {
        const float eps = 0.006f;
        float dx = query_trilinear({p.x + eps, p.y, p.z}) - query_trilinear({p.x - eps, p.y, p.z});
        float dy = query_trilinear({p.x, p.y + eps, p.z}) - query_trilinear({p.x, p.y - eps, p.z});
        float dz = query_trilinear({p.x, p.y, p.z + eps}) - query_trilinear({p.x, p.y, p.z - eps});
        Vec3 g = {dx, dy, dz};
        float n = norm(g);
        return (n < 1e-8f) ? Vec3{0, 0, 1} : g * (1.0f / n);
    }
};

struct Ball { Vec3 c; float radius; int start_idx, count; };
struct TubeBModel { std::vector<Ball> balls; std::vector<Vec3> pts; };

SDFGrid g_sdf;
TubeBModel g_fast, g_dense;

TubeBModel build_hierarchy(const std::vector<Vec3>& src, int n_fps, int n_balls) {
    int nb = (int)src.size();
    std::vector<Vec3> fps;
    fps.reserve(n_fps);
    std::vector<float> d2_fps(nb, 1e30f);
    fps.push_back(src[0]);
    for (int k = 0; k < n_fps; ++k) {
        const Vec3& c = fps[k];
        int far_i = 0; float max_d2 = -1.0f;
        for (int i = 0; i < nb; ++i) {
            float d2 = dot(src[i] - c, src[i] - c);
            if (d2 < d2_fps[i]) d2_fps[i] = d2;
            if (d2_fps[i] > max_d2) { max_d2 = d2_fps[i]; far_i = i; }
        }
        if (k + 1 < n_fps) fps.push_back(src[far_i]);
        else printf("  FPS %d pts: cover_r=%.5f m\n", n_fps, sqrtf(max_d2));
    }

    std::vector<Vec3> centers;
    centers.reserve(n_balls);
    std::vector<float> min_d2_c(n_fps, 1e30f);
    std::vector<int> assign(n_fps, 0);
    centers.push_back(fps[0]);
    for (int m = 0; m < n_balls; ++m) {
        const Vec3& c = centers[m];
        int far_i = 0; float max_d2 = -1.0f;
        for (int i = 0; i < n_fps; ++i) {
            float d2 = dot(fps[i] - c, fps[i] - c);
            if (d2 < min_d2_c[i]) { min_d2_c[i] = d2; assign[i] = m; }
            if (min_d2_c[i] > max_d2) { max_d2 = min_d2_c[i]; far_i = i; }
        }
        if (m + 1 < n_balls) centers.push_back(fps[far_i]);
    }

    std::vector<std::vector<Vec3>> buckets(n_balls);
    for (int i = 0; i < n_fps; ++i) buckets[assign[i]].push_back(fps[i]);
    TubeBModel mdl;
    mdl.balls.resize(n_balls);
    mdl.pts.reserve(n_fps);
    for (int m = 0; m < n_balls; ++m) {
        int st = (int)mdl.pts.size();
        float r = 0.0f;
        for (const Vec3& b : buckets[m]) {
            r = std::max(r, norm(b - centers[m]));
            mdl.pts.push_back(b);
        }
        mdl.balls[m] = {centers[m], r, st, (int)buckets[m].size()};
    }
    return mdl;
}

float eval_model(const TubeBModel& mdl, const Vec3& p, const Quat& q, float stop_below, bool trilinear = false) {
    if (p.x < -0.68f || p.x > 3.08f || p.y < -0.68f || p.y > 3.08f || p.z < -0.68f || p.z > 3.08f)
        return -1.0f;
    Mat3 R = q_to_mat(q);
    float min_clr = 10.0f;
    const int nb = (int)mdl.balls.size();
    static thread_local std::vector<float> ball_d;
    static thread_local std::vector<int> need;
    ball_d.resize(nb);
    need.clear();

    for (int m = 0; m < nb; ++m) {
        const Ball& b = mdl.balls[m];
        Vec3 w = p + R.apply(b.c);
        if (w.x < -0.76f || w.x > 3.16f || w.y < -0.76f || w.y > 3.16f || w.z < -0.76f || w.z > 3.16f)
            return -1.0f;
        float d = trilinear ? g_sdf.query_trilinear(w) : g_sdf.query_nearest(w);
        if (d < stop_below) return d;
        if (d < min_clr) min_clr = d;
        ball_d[m] = d;
        if (d - b.radius < stop_below || (stop_below < -5.0f && d - b.radius < min_clr)) {
            need.push_back(m);
        }
    }
    for (int m : need) {
        const Ball& b = mdl.balls[m];
        if (stop_below > -5.0f && ball_d[m] - b.radius >= stop_below) continue;
        if (stop_below <= -5.0f && ball_d[m] - b.radius >= min_clr) continue;
        const Vec3* ptr = &mdl.pts[b.start_idx];
        for (int i = 0; i < b.count; ++i) {
            Vec3 w = p + R.apply(ptr[i]);
            float d = trilinear ? g_sdf.query_trilinear(w) : g_sdf.query_nearest(w);
            if (d < stop_below) return d;
            if (d < min_clr) min_clr = d;
        }
    }
    return min_clr;
}

bool retract_pose(const TubeBModel& mdl, Vec3& p, Quat& q, float target_clr, int max_iters) {
    for (int it = 0; it < max_iters; ++it) {
        Mat3 R = q_to_mat(q);
        float min_d = 10.0f;
        struct Contact { Vec3 r_world; Vec3 w_world; float d; };
        static thread_local std::vector<Contact> contacts;
        contacts.clear();

        for (const Ball& b : mdl.balls) {
            Vec3 rw = R.apply(b.c);
            Vec3 w = p + rw;
            float d = g_sdf.query_trilinear(w);
            if (d - b.radius < target_clr + 0.028f) {
                const Vec3* ptr = &mdl.pts[b.start_idx];
                for (int i = 0; i < b.count; ++i) {
                    Vec3 rwi = R.apply(ptr[i]);
                    Vec3 wi = p + rwi;
                    float di = g_sdf.query_trilinear(wi);
                    if (di < min_d) min_d = di;
                    if (di < target_clr + 0.024f) contacts.push_back({rwi, wi, di});
                }
            } else if (d < min_d) min_d = d;
        }
        if (min_d >= target_clr || contacts.empty()) return min_d >= target_clr;

        Vec3 F = {0, 0, 0}, T = {0, 0, 0};
        float w_sum = 0.0f;
        for (const auto& c : contacts) {
            if (c.d > min_d + 0.018f) continue;
            float wt = expf(-(c.d - min_d) * 180.0f);
            Vec3 g = g_sdf.grad(c.w_world);
            F = F + g * wt;
            T = T + cross(c.r_world, g) * wt;
            w_sum += wt;
        }
        if (w_sum < 1e-8f) break;
        F = F * (1.0f / w_sum);
        T = T * (1.0f / w_sum);

        float scale = std::max(norm(F), 0.7f * norm(T));
        if (scale < 1e-6f) break;
        Vec3 dp_dir = F * (1.0f / scale);
        Vec3 dw_dir = T * (0.5f / scale);

        bool improved = false;
        float cur_exact = eval_model(mdl, p, q, -10.0f, true);
        for (float step : {0.010f, 0.005f, 0.002f, 0.0008f}) {
            Vec3 np = p + dp_dir * step;
            Quat nq = q_norm(q_mul(q_exp(dw_dir * step), q));
            float nc = eval_model(mdl, np, nq, cur_exact + 5e-5f, true);
            if (nc > cur_exact + 5e-5f) {
                p = np; q = nq; improved = true; break;
            }
        }
        if (!improved) break;
    }
    return eval_model(mdl, p, q, target_clr, true) >= target_clr;
}

bool edge_valid_fast(const Vec3& p1, const Quat& q1, const Vec3& p2, const Quat& q2, float d_req, int n_sub = 4) {
    for (int s = 1; s <= n_sub; ++s) {
        float t = (float)s / (float)n_sub;
        if (eval_model(g_fast, p1 + (p2 - p1) * t, q_slerp(q1, q2, t), d_req) < d_req) return false;
    }
    return true;
}

// Dense continuous clearance of a single rig step (checking BOTH sync and async 0.1m/s, 0.1rad/s!)
float step_min_clr_dense(const Vec3& p1, const Quat& q1, const Vec3& p2, const Quat& q2, float stop_below, int n_sub = 16) {
    float lin = norm(p2 - p1);
    float ang = q_angle(q1, q2);
    if (lin > 0.095f || ang > 0.185f) return -1.0f;

    float mc = 10.0f;
    for (int s = 0; s <= n_sub; ++s) {
        float t = (float)s / (float)n_sub;
        float c = eval_model(g_dense, p1 + (p2 - p1) * t, q_slerp(q1, q2, t), stop_below, true);
        if (c < stop_below) return c;
        if (c < mc) mc = c;
    }
    float T_lin = lin / 0.1f, T_ang = ang / 0.1f;
    float T_tot = std::max({T_lin, T_ang, 1e-6f});
    if (fabsf(T_lin - T_ang) > 1e-3f) {
        for (int s = 1; s < n_sub; ++s) {
            float tau = T_tot * ((float)s / (float)n_sub);
            float tl = (T_lin > 1e-6f) ? std::min(1.0f, tau / T_lin) : 1.0f;
            float ta = (T_ang > 1e-6f) ? std::min(1.0f, tau / T_ang) : 1.0f;
            float c = eval_model(g_dense, p1 + (p2 - p1) * tl, q_slerp(q1, q2, ta), stop_below, true);
            if (c < stop_below) return c;
            if (c < mc) mc = c;
        }
    }
    return mc;
}

struct Node { Vec3 p; Quat q; int parent; };
inline float pose_dist(const Vec3& p1, const Quat& q1, const Vec3& p2, const Quat& q2) {
    return norm(p1 - p2) + 1.1f * q_angle(q1, q2);
}

int nearest_node(const std::vector<Node>& tree, const Vec3& p, const Quat& q) {
    int best = 0; float bd = 1e30f;
    for (int i = 0; i < (int)tree.size(); ++i) {
        float ld = norm(tree[i].p - p);
        if (ld >= bd) continue;
        float d = ld + 1.1f * q_angle(tree[i].q, q);
        if (d < bd) { bd = d; best = i; }
    }
    return best;
}

int extend_tree(std::vector<Node>& tree, int near_idx, const Vec3& tp, const Quat& tq, float d_req) {
    const Vec3 p0 = tree[near_idx].p;
    const Quat q0 = tree[near_idx].q;
    float lin = norm(tp - p0), ang = q_angle(q0, tq);
    float frac = 1.0f;
    if (lin > 0.040f) frac = std::min(frac, 0.040f / lin);
    if (ang > 0.050f) frac = std::min(frac, 0.050f / ang);

    Vec3 np = p0 + (tp - p0) * frac;
    Quat nq = q_slerp(q0, tq, frac);
    if (edge_valid_fast(p0, q0, np, nq, d_req, 3)) {
        tree.push_back({np, nq, near_idx});
        return (int)tree.size() - 1;
    }
    Vec3 sp = np; Quat sq = nq;
    if (retract_pose(g_fast, sp, sq, d_req + 0.003f, 4)) {
        if (norm(sp - p0) <= 0.065f && q_angle(q0, sq) <= 0.085f &&
            pose_dist(p0, q0, sp, sq) > 0.010f && edge_valid_fast(p0, q0, sp, sq, d_req, 4)) {
            tree.push_back({sp, sq, near_idx});
            return (int)tree.size() - 1;
        }
    }
    return -1;
}

int main() {
    auto t_start = std::chrono::steady_clock::now();
    FILE* fa = fopen("/tmp/opencode/allA_t4.bin", "rb");
    FILE* fb = fopen("/tmp/opencode/surfB_t4.bin", "rb");
    uint32_t na, nb;
    if (fread(&na, 4, 1, fa) != 1) return 1;
    std::vector<Vec3> allA(na);
    if (fread(allA.data(), sizeof(Vec3), na, fa) != na) return 1;
    fclose(fa);
    if (fread(&nb, 4, 1, fb) != 1) return 1;
    std::vector<Vec3> surfB_world(nb);
    if (fread(surfB_world.data(), sizeof(Vec3), nb, fb) != nb) return 1;
    fclose(fb);

    g_sdf.h = 0.006f; g_sdf.inv_h = 1.0f / g_sdf.h;
    g_sdf.x0 = -0.675f; g_sdf.y0 = -0.725f; g_sdf.z0 = -0.771f;
    g_sdf.NX = 608; g_sdf.NY = 488; g_sdf.NZ = 304;
    size_t N_grid = (size_t)g_sdf.NX * g_sdf.NY * g_sdf.NZ;
    g_sdf.aabb_min = {1e9f,1e9f,1e9f}; g_sdf.aabb_max = {-1e9f,-1e9f,-1e9f};
    std::vector<uint8_t> occ(N_grid, 0);
    for (const Vec3& p : allA) {
        g_sdf.aabb_min.x = std::min(g_sdf.aabb_min.x, p.x); g_sdf.aabb_max.x = std::max(g_sdf.aabb_max.x, p.x);
        g_sdf.aabb_min.y = std::min(g_sdf.aabb_min.y, p.y); g_sdf.aabb_max.y = std::max(g_sdf.aabb_max.y, p.y);
        g_sdf.aabb_min.z = std::min(g_sdf.aabb_min.z, p.z); g_sdf.aabb_max.z = std::max(g_sdf.aabb_max.z, p.z);
        int ix = (int)floorf((p.x - g_sdf.x0) * g_sdf.inv_h);
        int iy = (int)floorf((p.y - g_sdf.y0) * g_sdf.inv_h);
        int iz = (int)floorf((p.z - g_sdf.z0) * g_sdf.inv_h);
        if ((unsigned)ix < (unsigned)g_sdf.NX && (unsigned)iy < (unsigned)g_sdf.NY && (unsigned)iz < (unsigned)g_sdf.NZ)
            occ[((size_t)iz * g_sdf.NY + iy) * g_sdf.NX + ix] = 1;
    }
    const float INF_SQ = 1e12f;
    std::vector<float> edt_out(N_grid), edt_in(N_grid);
    for (size_t i = 0; i < N_grid; ++i) {
        edt_out[i] = occ[i] ? 0.0f : INF_SQ;
        edt_in[i]  = occ[i] ? INF_SQ : 0.0f;
    }
    occ.clear(); occ.shrink_to_fit();
    edt_3d(edt_out, g_sdf.NX, g_sdf.NY, g_sdf.NZ);
    edt_3d(edt_in,  g_sdf.NX, g_sdf.NY, g_sdf.NZ);
    g_sdf.sdf_mm10.resize(N_grid);
    for (size_t i = 0; i < N_grid; ++i) {
        float raw = (edt_out[i] > 0.0f) ? (sqrtf(edt_out[i]) - 0.5f) * g_sdf.h : -(sqrtf(edt_in[i]) - 0.5f) * g_sdf.h;
        g_sdf.sdf_mm10[i] = (int16_t)std::max(-32000, std::min(32000, (int)lrintf(raw * 1e4f)));
    }
    edt_out.clear(); edt_out.shrink_to_fit();
    edt_in.clear();  edt_in.shrink_to_fit();

    Vec3 p0 = {1.2f, 0.36f, 0.28f};
    Quat q0 = {1.0f, 0.0f, 0.0f, 0.0f};
    std::vector<Vec3> full_localB(nb);
    for (uint32_t i = 0; i < nb; ++i) full_localB[i] = surfB_world[i] - p0;

    printf("Building fast (1600) and dense (10000) hierarchies...\n");
    g_fast  = build_hierarchy(full_localB, 1600,  160);
    g_dense = build_hierarchy(full_localB, 10000, 250);

    float raw_t0 = eval_model(g_dense, p0, q0, -10.0f, true);
    int cal_mm10 = (int)lrintf((0.04445f - raw_t0) * 1e4f);
    for (size_t i = 0; i < N_grid; ++i) {
        int v = (int)g_sdf.sdf_mm10[i] + cal_mm10;
        g_sdf.sdf_mm10[i] = (int16_t)std::max(-32000, std::min(32000, v));
    }
    printf("Calibrated t=0 dense clearance = %.5f m (offset=%+.5f m)\n",
           eval_model(g_dense, p0, q0, -10.0f, true), cal_mm10 * 1e-4f);
    fflush(stdout);

    std::vector<std::pair<Vec3, Quat>> goals;
    std::mt19937 rng_goal(42);
    std::uniform_real_distribution<float> up(-0.55f, 2.95f), u01(0.0f, 1.0f);
    while (goals.size() < 28) {
        Vec3 gp = {up(rng_goal), up(rng_goal), up(rng_goal)};
        float u1 = u01(rng_goal), u2 = u01(rng_goal) * 2.0f * (float)M_PI, u3 = u01(rng_goal) * 2.0f * (float)M_PI;
        Quat gq = q_norm({sqrtf(1.0f - u1)*sinf(u2), sqrtf(1.0f - u1)*cosf(u2), sqrtf(u1)*sinf(u3), sqrtf(u1)*cosf(u3)});
        if (eval_model(g_dense, gp, gq, 0.48f, true) >= 0.48f) goals.push_back({gp, gq});
    }

    struct CandSol { float d_req; std::vector<std::pair<Vec3, Quat>> path; };
    std::mutex sol_mtx;
    std::vector<CandSol> solutions;

    float thread_dreq[10] = {
        0.011f, 0.010f, 0.009f, 0.008f,
        0.0075f, 0.007f, 0.0065f, 0.006f,
        0.0055f, 0.005f
    };

    auto worker = [&](int tid) {
        float d_req = thread_dreq[tid];
        std::mt19937 rng(7001 + tid * 1337);
        std::uniform_real_distribution<float> u(0.0f, 1.0f);
        std::normal_distribution<float> gauss(0.0f, 1.0f);

        std::vector<Node> tA, tB;
        tA.reserve(40000); tB.reserve(40000);
        tA.push_back({p0, q0, -1});
        for (const auto& g : goals) tB.push_back({g.first, g.second, -1});

        for (int iter = 0; iter < 150000; ++iter) {
            if ((iter & 127) == 0) {
                double sec = std::chrono::duration<double>(std::chrono::steady_clock::now() - t_start).count();
                if (sec > 28.0) break;
            }
            float u1 = u(rng), u2 = u(rng) * 2.0f * (float)M_PI, u3 = u(rng) * 2.0f * (float)M_PI;
            Quat sq = q_norm({sqrtf(1.0f - u1)*sinf(u2), sqrtf(1.0f - u1)*cosf(u2), sqrtf(u1)*sinf(u3), sqrtf(u1)*cosf(u3)});
            Vec3 sp;
            float mode = u(rng);
            if (mode < 0.50f) {
                sp = {-0.3f + u(rng)*3.1f, -0.4f + u(rng)*2.3f, -0.4f + u(rng)*1.6f};
            } else if (mode < 0.75f) {
                sp = {-0.6f + u(rng)*3.6f, -0.6f + u(rng)*3.6f, -0.6f + u(rng)*3.6f};
            } else {
                const auto& src = (tA.size() <= tB.size()) ? tA : tB;
                int idx = rng() % src.size();
                sp = src[idx].p + Vec3{gauss(rng)*0.18f, gauss(rng)*0.18f, gauss(rng)*0.18f};
                sq = q_norm(q_mul(q_exp({gauss(rng)*0.25f, gauss(rng)*0.25f, gauss(rng)*0.25f}), src[idx].q));
            }

            bool swap_trees = (tA.size() > tB.size());
            auto& tree1 = swap_trees ? tB : tA;
            auto& tree2 = swap_trees ? tA : tB;

            int n1 = nearest_node(tree1, sp, sq);
            int added1 = extend_tree(tree1, n1, sp, sq, d_req);
            if (added1 != -1) {
                for (int c = 0; c < 6; ++c) {
                    if (pose_dist(tree1[added1].p, tree1[added1].q, sp, sq) < 0.045f) break;
                    int nxt = extend_tree(tree1, added1, sp, sq, d_req);
                    if (nxt == -1) break;
                    added1 = nxt;
                }
                const Vec3 target_p = tree1[added1].p;
                const Quat target_q = tree1[added1].q;
                int cur2 = nearest_node(tree2, target_p, target_q);
                for (int step = 0; step < 35; ++step) {
                    if (pose_dist(tree2[cur2].p, tree2[cur2].q, target_p, target_q) < 0.065f &&
                        edge_valid_fast(tree2[cur2].p, tree2[cur2].q, target_p, target_q, d_req, 5)) {
                        int idxA = swap_trees ? cur2 : added1;
                        int idxB = swap_trees ? added1 : cur2;
                        std::vector<std::pair<Vec3, Quat>> path;
                        for (int c = idxA; c != -1; c = tA[c].parent) path.push_back({tA[c].p, tA[c].q});
                        std::reverse(path.begin(), path.end());
                        for (int c = idxB; c != -1; c = tB[c].parent) path.push_back({tB[c].p, tB[c].q});

                        std::lock_guard<std::mutex> lk(sol_mtx);
                        printf("[Thread %d, d_req=%.4f] CONNECTED at iter %d (raw_nodes=%zu)\n",
                               tid, d_req, iter, path.size());
                        fflush(stdout);
                        solutions.push_back({d_req, path});
                        return;
                    }
                    int nxt2 = extend_tree(tree2, cur2, target_p, target_q, d_req);
                    if (nxt2 == -1) break;
                    cur2 = nxt2;
                }
            }
        }
    };

    std::vector<std::thread> threads;
    for (int t = 0; t < 10; ++t) threads.emplace_back(worker, t);
    for (auto& th : threads) th.join();

    if (solutions.empty()) {
        printf("No solution found!\n");
        return 2;
    }

    // Optimize each top candidate (up to 3 highest d_req / shortest) and pick the highest dense-clearance + shortest!
    std::sort(solutions.begin(), solutions.end(), [](const CandSol& a, const CandSol& b) {
        if (fabsf(a.d_req - b.d_req) > 1e-4f) return a.d_req > b.d_req;
        return a.path.size() < b.path.size();
    });

    auto discretize_adaptive = [](const Vec3& a_p, const Quat& a_q, const Vec3& b_p, const Quat& b_q, bool cautious) {
        float lin = norm(b_p - a_p);
        float ang = q_angle(a_q, b_q);
        float ml = cautious ? 0.046f : 0.092f;
        float ma = cautious ? 0.088f : 0.178f;
        int n = std::max({1, (int)ceilf(lin / ml), (int)ceilf(ang / ma)});
        std::vector<std::pair<Vec3, Quat>> seg;
        seg.reserve(n);
        for (int k = 1; k <= n; ++k) {
            float t = (float)k / (float)n;
            seg.push_back({a_p + (b_p - a_p) * t, q_slerp(a_q, b_q, t)});
        }
        return seg;
    };

    std::vector<std::pair<Vec3, Quat>> best_final_path;
    float best_final_clr = -10.0f;

    int n_try = std::min((int)solutions.size(), 3);
    for (int si = 0; si < n_try; ++si) {
        auto raw = solutions[si].path;
        for (size_t i = 1; i < raw.size(); ++i) {
            if (eval_model(g_dense, raw[i].first, raw[i].second, 0.46f, true) >= 0.46f) {
                raw.resize(i + 1);
                break;
            }
        }
        // Fine initial discretization (cautious everywhere first so we can boost clearance!)
        std::vector<std::pair<Vec3, Quat>> path;
        path.push_back(raw[0]);
        for (size_t i = 0; i + 1 < raw.size(); ++i) {
            auto seg = discretize_adaptive(raw[i].first, raw[i].second, raw[i+1].first, raw[i+1].second, true);
            path.insert(path.end(), seg.begin(), seg.end());
        }

        // Elastic-band + random coordinate hill-climbing on g_dense to MAXIMIZE bottleneck clearance!
        std::mt19937 hrng(999 + si);
        std::normal_distribution<float> hg(0.0f, 1.0f);
        for (int pass = 0; pass < 15; ++pass) {
            for (size_t i = 1; i + 1 < path.size(); ++i) {
                float c_prev = step_min_clr_dense(path[i-1].first, path[i-1].second, path[i].first, path[i].second, -10.0f, 10);
                float c_next = step_min_clr_dense(path[i].first, path[i].second, path[i+1].first, path[i+1].second, -10.0f, 10);
                float cur_local = std::min(c_prev, c_next);
                if (cur_local >= 0.032f) continue;

                // Try midpoint smoothing + SDF retraction
                Vec3 mp = (path[i-1].first + path[i].first * 2.0f + path[i+1].first) * 0.25f;
                Quat mq = q_slerp(path[i].second, q_slerp(path[i-1].second, path[i+1].second, 0.5f), 0.35f);
                retract_pose(g_dense, mp, mq, 0.035f, 4);
                if (norm(mp - path[i-1].first) <= 0.092f && q_angle(path[i-1].second, mq) <= 0.178f &&
                    norm(path[i+1].first - mp) <= 0.092f && q_angle(mq, path[i+1].second) <= 0.178f) {
                    float n1 = step_min_clr_dense(path[i-1].first, path[i-1].second, mp, mq, cur_local, 10);
                    if (n1 > cur_local) {
                        float n2 = step_min_clr_dense(mp, mq, path[i+1].first, path[i+1].second, cur_local, 10);
                        if (std::min(n1, n2) > cur_local) {
                            path[i] = {mp, mq};
                            cur_local = std::min(n1, n2);
                        }
                    }
                }
                // Random local perturbation hill-climb for bottleneck nodes!
                if (cur_local < 0.015f) {
                    float rad_p = (pass < 7) ? 0.005f : 0.0018f;
                    float rad_q = (pass < 7) ? 0.008f : 0.0030f;
                    for (int tr = 0; tr < 12; ++tr) {
                        Vec3 tp = path[i].first + Vec3{hg(hrng)*rad_p, hg(hrng)*rad_p, hg(hrng)*rad_p};
                        Quat tq = q_norm(q_mul(q_exp({hg(hrng)*rad_q, hg(hrng)*rad_q, hg(hrng)*rad_q}), path[i].second));
                        if (norm(tp - path[i-1].first) > 0.092f || q_angle(path[i-1].second, tq) > 0.178f ||
                            norm(path[i+1].first - tp) > 0.092f || q_angle(tq, path[i+1].second) > 0.178f) continue;
                        float n1 = step_min_clr_dense(path[i-1].first, path[i-1].second, tp, tq, cur_local + 2e-5f, 10);
                        if (n1 > cur_local + 2e-5f) {
                            float n2 = step_min_clr_dense(tp, tq, path[i+1].first, path[i+1].second, cur_local + 2e-5f, 10);
                            if (std::min(n1, n2) > cur_local + 2e-5f) {
                                path[i] = {tp, tq};
                                cur_local = std::min(n1, n2);
                            }
                        }
                    }
                }
            }
        }

        // Segment-local clearance-preserving shortcutting!
        auto subpath_min_clr = [&](int a, int b) {
            float mc = 10.0f;
            for (int k = a; k < b; ++k) {
                mc = std::min(mc, step_min_clr_dense(path[k].first, path[k].second, path[k+1].first, path[k+1].second, -10.0f, 12));
            }
            return mc;
        };

        for (int it = 0; it < 1200; ++it) {
            if (path.size() <= 3) break;
            int i = hrng() % (path.size() - 1);
            int j = hrng() % path.size();
            if (i > j) std::swap(i, j);
            if (j - i <= 1) continue;

            float orig_clr = subpath_min_clr(i, j);
            float req_clr = std::min(0.018f, orig_clr - 0.0003f);
            bool cautious = (orig_clr < 0.018f);
            auto cand = discretize_adaptive(path[i].first, path[i].second, path[j].first, path[j].second, cautious);
            if ((int)cand.size() >= j - i) continue;

            bool ok = true;
            Vec3 pp = path[i].first; Quat pq = path[i].second;
            for (const auto& wp : cand) {
                if (step_min_clr_dense(pp, pq, wp.first, wp.second, req_clr, 16) < req_clr) {
                    ok = false; break;
                }
                pp = wp.first; pq = wp.second;
            }
            if (ok) {
                std::vector<std::pair<Vec3, Quat>> nxt;
                nxt.insert(nxt.end(), path.begin(), path.begin() + i + 1);
                nxt.insert(nxt.end(), cand.begin(), cand.end());
                nxt.insert(nxt.end(), path.begin() + j + 1, path.end());
                path.swap(nxt);
            }
        }

        // Deterministic greedy sweep
        bool changed = true;
        while (changed) {
            changed = false;
            int N = (int)path.size();
            for (int i = 0; i < N - 2 && !changed; ++i) {
                for (int j = N - 1; j >= i + 2; --j) {
                    float orig_clr = subpath_min_clr(i, j);
                    float req_clr = std::min(0.018f, orig_clr - 0.0002f);
                    bool cautious = (orig_clr < 0.018f);
                    auto cand = discretize_adaptive(path[i].first, path[i].second, path[j].first, path[j].second, cautious);
                    if ((int)cand.size() >= j - i) continue;
                    bool ok = true;
                    Vec3 pp = path[i].first; Quat pq = path[i].second;
                    for (const auto& wp : cand) {
                        if (step_min_clr_dense(pp, pq, wp.first, wp.second, req_clr, 18) < req_clr) { ok = false; break; }
                        pp = wp.first; pq = wp.second;
                    }
                    if (ok) {
                        std::vector<std::pair<Vec3, Quat>> nxt;
                        nxt.insert(nxt.end(), path.begin(), path.begin() + i + 1);
                        nxt.insert(nxt.end(), cand.begin(), cand.end());
                        nxt.insert(nxt.end(), path.begin() + j + 1, path.end());
                        path.swap(nxt);
                        changed = true;
                        break;
                    }
                }
            }
        }

        float tot_mc = subpath_min_clr(0, (int)path.size() - 1);
        printf("Candidate %d (from d_req=%.4f): %zu move steps, min_dense_clr=%.5f m\n",
               si, solutions[si].d_req, path.size() - 1, tot_mc);
        if (tot_mc > best_final_clr || (fabsf(tot_mc - best_final_clr) < 0.0005f && path.size() < best_final_path.size())) {
            best_final_clr = tot_mc;
            best_final_path = path;
        }
    }

    // Final verification against ALL 89,448 surfB points!
    printf("\nVerifying best plan (%zu moves) on ALL %u surface voxels at 20 substeps/move...\n",
           best_final_path.size() - 1, nb);
    float exact_all_min = 10.0f;
    for (size_t k = 0; k + 1 < best_final_path.size(); ++k) {
        const auto& a = best_final_path[k];
        const auto& b = best_final_path[k + 1];
        float step_mc = 10.0f;
        for (int s = 0; s <= 20; ++s) {
            float t = s / 20.0f;
            Vec3 p = a.first + (b.first - a.first) * t;
            Mat3 R = q_to_mat(q_slerp(a.second, b.second, t));
            for (uint32_t i = 0; i < nb; i += 2) {
                float d = g_sdf.query_trilinear(p + R.apply(full_localB[i]));
                if (d < step_mc) step_mc = d;
            }
        }
        exact_all_min = std::min(exact_all_min, step_mc);
        printf("  Step %2zu: lin=%.4f m, ang=%.4f rad, min_clr=%.5f m\n",
               k + 1, norm(b.first - a.first), q_angle(a.second, b.second), step_mc);
    }
    float end_clr = eval_model(g_dense, best_final_path.back().first, best_final_path.back().second, -10.0f, true);
    printf("VERIFIED FULL-SURFACE MIN CLEARANCE = %.5f m | END SEPARATION = %.5f m\n", exact_all_min, end_clr);

    FILE* fout = fopen("/tmp/opencode/waypoints.json", "w");
    fprintf(fout, "{\n  \"min_clearance_m\": %.6f,\n  \"final_separation_m\": %.6f,\n  \"waypoints\": [\n",
            exact_all_min, end_clr);
    for (size_t i = 0; i < best_final_path.size(); ++i) {
        const auto& wp = best_final_path[i];
        fprintf(fout, "    {\"pos\": [%.6f, %.6f, %.6f], \"quat\": [%.7f, %.7f, %.7f, %.7f]}%s\n",
                wp.first.x, wp.first.y, wp.first.z,
                wp.second.w, wp.second.x, wp.second.y, wp.second.z,
                (i + 1 < best_final_path.size()) ? "," : "");
    }
    fprintf(fout, "  ]\n}\n");
    fclose(fout);
    return 0;
}

