#include <random>

struct Vec3 {
    float x, y, z;
    Vec3 operator+(const Vec3& o) const { return {x + o.x, y + o.y, z + o.z}; }
    Vec3 operator-(const Vec3& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }
};
inline float dot(const Vec3& a, const Vec3& b) { return a.x*b.x + a.y*b.y + a.z*b.z; }
inline float norm(const Vec3& a) { return sqrtf(dot(a, a)); }

struct Quat { float w, x, y, z; };
inline Quat q_norm(const Quat& q) {
    float n = sqrtf(q.w*q.w + q.x*q.x + q.y*q.y + q.z*q.z);
    Quat r = {q.w/n, q.x/n, q.y/n, q.z/n};
    return (r.w < 0) ? Quat{-r.w, -r.x, -r.y, -r.z} : r;
}
inline Quat q_mul(const Quat& a, const Quat& b) {
    return {a.w*b.w - a.x*b.x - a.y*b.y - a.z*b.z,
            a.w*b.x + a.x*b.w + a.y*b.z - a.z*b.y,
            a.w*b.y - a.x*b.z + a.y*b.w + a.z*b.x,
            a.w*b.z + a.x*b.y - a.y*b.x + a.z*b.w};
}
inline Quat q_exp(const Vec3& w) {
    float th = norm(w);
    if (th < 1e-7f) return q_norm({1.0f, 0.5f*w.x, 0.5f*w.y, 0.5f*w.z});
    float s = sinf(0.5f*th)/th;
    return q_norm({cosf(0.5f*th), w.x*s, w.y*s, w.z*s});
}
inline float q_angle(const Quat& a, const Quat& b) {
    float d = fabsf(a.w*b.w + a.x*b.x + a.y*b.y + a.z*b.z);
    return (d >= 1.0f) ? 0.0f : 2.0f * acosf(d);
}
inline Quat q_slerp(const Quat& a, Quat b, float t) {
    float d = a.w*b.w + a.x*b.x + a.y*b.y + a.z*b.z;
    if (d < 0.0f) { d = -d; b = {-b.w, -b.x, -b.y, -b.z}; }
    if (d > 0.9995f) return q_norm({a.w + t*(b.w-a.w), a.x + t*(b.x-a.x), a.y + t*(b.y-a.y), a.z + t*(b.z-a.z)});
    float th0 = acosf(std::min(1.0f, d)), th = th0 * t;
    float s0 = cosf(th) - d * sinf(th) / sinf(th0), s1 = sinf(th) / sinf(th0);
    return q_norm({s0*a.w + s1*b.w, s0*a.x + s1*b.x, s0*a.y + s1*b.y, s0*a.z + s1*b.z});
}
struct Mat3 {
    float m[9];
    inline Vec3 apply(const Vec3& v) const {
        return {m[0]*v.x + m[1]*v.y + m[2]*v.z,
                m[3]*v.x + m[4]*v.y + m[5]*v.z,
                m[6]*v.x + m[7]*v.y + m[8]*v.z};
    }
};
inline Mat3 q_to_mat(const Quat& q) {
    float xx=q.x*q.x, yy=q.y*q.y, zz=q.z*q.z, xy=q.x*q.y, xz=q.x*q.z, yz=q.y*q.z, wx=q.w*q.x, wy=q.w*q.y, wz=q.w*q.z;
    return {{1-2*(yy+zz), 2*(xy-wz), 2*(xz+wy), 2*(xy+wz), 1-2*(xx+zz), 2*(yz-wx), 2*(xz-wy), 2*(yz+wx), 1-2*(xx+yy)}};
}

void edt_1d(const float* f, float* d, int n, int* v, float* z) {
    int k = 0; v[0] = 0; z[0] = -1e20f; z[1] = +1e20f;
    for (int q = 1; q < n; ++q) {
        float s;
        while (true) { int vk = v[k]; s = ((f[q] + q*q) - (f[vk] + vk*vk)) / (2.0f * (q - vk)); if (s <= z[k]) k--; else break; }
        k++; v[k] = q; z[k] = s; z[k + 1] = +1e20f;
    }
    k = 0;
    for (int q = 0; q < n; ++q) { while (z[k + 1] < q) k++; float dx = (float)(q - v[k]); d[q] = dx*dx + f[v[k]]; }
}
void edt_3d(std::vector<float>& grid, int NX, int NY, int NZ) {
    int maxN = std::max({NX, NY, NZ});
    std::vector<float> f(maxN), d(maxN), z(maxN + 2); std::vector<int> v(maxN + 1);
    for (int iz = 0; iz < NZ; ++iz) for (int iy = 0; iy < NY; ++iy) { float* r = &grid[((size_t)iz*NY+iy)*NX]; for (int ix=0;ix<NX;++ix) f[ix]=r[ix]; edt_1d(f.data(), r, NX, v.data(), z.data()); }
    for (int iz = 0; iz < NZ; ++iz) for (int ix = 0; ix < NX; ++ix) { for (int iy=0;iy<NY;++iy) f[iy]=grid[((size_t)iz*NY+iy)*NX+ix]; edt_1d(f.data(), d.data(), NY, v.data(), z.data()); for (int iy=0;iy<NY;++iy) grid[((size_t)iz*NY+iy)*NX+ix]=d[iy]; }
    for (int iy = 0; iy < NY; ++iy) for (int ix = 0; ix < NX; ++ix) { for (int iz=0;iz<NZ;++iz) f[iz]=grid[((size_t)iz*NY+iy)*NX+ix]; edt_1d(f.data(), d.data(), NZ, v.data(), z.data()); for (int iz=0;iz<NZ;++iz) grid[((size_t)iz*NY+iy)*NX+ix]=d[iz]; }
}

int main() {
    FILE* fa = fopen("/tmp/opencode/allA_t4.bin", "rb");
    FILE* fb = fopen("/tmp/opencode/surfB_t4.bin", "rb");
    uint32_t na, nb;
    if (fread(&na, 4, 1, fa) != 1) return 1;
    std::vector<Vec3> allA(na); if (fread(allA.data(), sizeof(Vec3), na, fa) != na) return 1; fclose(fa);
    if (fread(&nb, 4, 1, fb) != 1) return 1;
    std::vector<Vec3> surfB_w(nb); if (fread(surfB_w.data(), sizeof(Vec3), nb, fb) != nb) return 1; fclose(fb);

    float h = 0.006f, inv_h = 1.0f/h, x0 = -0.675f, y0 = -0.725f, z0 = -0.771f;
    int NX = 608, NY = 488, NZ = 304;
    size_t N_grid = (size_t)NX*NY*NZ;
    Vec3 amin={1e9f,1e9f,1e9f}, amax={-1e9f,-1e9f,-1e9f};
    std::vector<uint8_t> occ(N_grid, 0);
    for (auto& p : allA) {
        amin.x=std::min(amin.x,p.x); amax.x=std::max(amax.x,p.x);
        amin.y=std::min(amin.y,p.y); amax.y=std::max(amax.y,p.y);
        amin.z=std::min(amin.z,p.z); amax.z=std::max(amax.z,p.z);
        int ix=(int)floorf((p.x-x0)*inv_h), iy=(int)floorf((p.y-y0)*inv_h), iz=(int)floorf((p.z-z0)*inv_h);
        occ[((size_t)iz*NY+iy)*NX+ix] = 1;
    }
    std::vector<float> e_out(N_grid), e_in(N_grid);
    for (size_t i=0;i<N_grid;++i) { e_out[i]=occ[i]?0:1e12f; e_in[i]=occ[i]?1e12f:0; }
    edt_3d(e_out, NX, NY, NZ); edt_3d(e_in, NX, NY, NZ);
    std::vector<float> sdf(N_grid);
    for (size_t i=0;i<N_grid;++i) sdf[i] = (e_out[i]>0) ? (sqrtf(e_out[i])-0.5f)*h : -(sqrtf(e_in[i])-0.5f)*h;

    auto q_tri = [&](const Vec3& p) -> float {
        float gx=(p.x-x0)*inv_h-0.5f, gy=(p.y-y0)*inv_h-0.5f, gz=(p.z-z0)*inv_h-0.5f;
        int ix=(int)floorf(gx), iy=(int)floorf(gy), iz=(int)floorf(gz);
        if (ix<0 || ix+1>=NX || iy<0 || iy+1>=NY || iz<0 || iz+1>=NZ) {
            float dx=std::max({0.0f,amin.x-p.x,p.x-amax.x});
            float dy=std::max({0.0f,amin.y-p.y,p.y-amax.y});
            float dz=std::max({0.0f,amin.z-p.z,p.z-amax.z});
            return sqrtf(dx*dx+dy*dy+dz*dz);
        }
        float tx=gx-ix, ty=gy-iy, tz=gz-iz;
        size_t b00=((size_t)iz*NY+iy)*NX+ix, b10=b00+NX, b01=b00+(size_t)NY*NX, b11=b01+NX;
        float c00=sdf[b00]*(1-tx)+sdf[b00+1]*tx, c10=sdf[b10]*(1-tx)+sdf[b10+1]*tx;
        float c01=sdf[b01]*(1-tx)+sdf[b01+1]*tx, c11=sdf[b11]*(1-tx)+sdf[b11+1]*tx;
        return (c00*(1-ty)+c10*ty)*(1-tz) + (c01*(1-ty)+c11*ty)*tz;
    };

    Vec3 p0={1.2f, 0.36f, 0.28f};
    std::vector<Vec3> fullB(nb);
    float raw_t0 = 10.0f;
    for (uint32_t i=0;i<nb;++i) {
        fullB[i] = surfB_w[i] - p0;
        raw_t0 = std::min(raw_t0, q_tri(surfB_w[i]));
    }
    float cal = 0.04445f - raw_t0;
    for (float& v : sdf) v += cal;

    // Build exact 300-ball hierarchy over ALL 89,448 points!
    const int MB = 300;
    std::vector<Vec3> centers; centers.push_back(fullB[0]);
    std::vector<float> md2(nb, 1e30f); std::vector<int> asgn(nb, 0);
    for (int m=0;m<MB;++m) {
        int far=0; float mx=-1;
        for (uint32_t i=0;i<nb;++i) {
            float d2=dot(fullB[i]-centers[m], fullB[i]-centers[m]);
            if (d2<md2[i]) { md2[i]=d2; asgn[i]=m; }
            if (md2[i]>mx) { mx=md2[i]; far=i; }
        }
        if (m+1<MB) centers.push_back(fullB[far]);
    }
    struct Ball { Vec3 c; float r; std::vector<Vec3> pts; };
    std::vector<Ball> balls(MB);
    for (int m=0;m<MB;++m) { balls[m].c = centers[m]; balls[m].r = 0; }
    for (uint32_t i=0;i<nb;++i) {
        int m = asgn[i];
        balls[m].r = std::max(balls[m].r, norm(fullB[i] - balls[m].c));
        balls[m].pts.push_back(fullB[i]);
    }

    auto exact_clr = [&](const Vec3& p, const Quat& q, float stop_below) -> float {
        Mat3 R = q_to_mat(q);
        float mc = 10.0f;
        std::vector<float> bd(MB);
        for (int m=0;m<MB;++m) {
            float d = q_tri(p + R.apply(balls[m].c));
            if (d < stop_below) return d;
            if (d < mc) mc = d;
            bd[m] = d;
        }
        for (int m=0;m<MB;++m) {
            if (stop_below > -5.0f && bd[m] - balls[m].r >= stop_below) continue;
            if (stop_below <= -5.0f && bd[m] - balls[m].r >= mc) continue;
            for (const Vec3& b : balls[m].pts) {
                float d = q_tri(p + R.apply(b));
                if (d < stop_below) return d;
                if (d < mc) mc = d;
            }
        }
        return mc;
    };

    auto step_exact = [&](const Vec3& p1, const Quat& q1, const Vec3& p2, const Quat& q2, float stop_below) -> float {
        float lin = norm(p2 - p1), ang = q_angle(q1, q2);
        if (lin > 0.096f || ang > 0.188f) return -1.0f;
        float mc = 10.0f;
        for (int s = 0; s <= 14; ++s) {
            float t = s / 14.0f;
            float c = exact_clr(p1 + (p2 - p1)*t, q_slerp(q1, q2, t), stop_below);
            if (c < stop_below) return c;
            mc = std::min(mc, c);
        }
        float Tl = lin/0.1f, Ta = ang/0.1f, Tt = std::max({Tl, Ta, 1e-6f});
        if (fabsf(Tl - Ta) > 1e-3f) {
            for (int s = 1; s < 14; ++s) {
                float tau = Tt * (s / 14.0f);
                float tl = (Tl > 1e-6f) ? std::min(1.0f, tau/Tl) : 1.0f;
                float ta = (Ta > 1e-6f) ? std::min(1.0f, tau/Ta) : 1.0f;
                float c = exact_clr(p1 + (p2 - p1)*tl, q_slerp(q1, q2, ta), stop_below);
                if (c < stop_below) return c;
                mc = std::min(mc, c);
            }
        }
        return mc;
    };

    // Parse waypoints.json
    std::ifstream ifs("/tmp/opencode/waypoints.json");
    std::string line;
    std::vector<std::pair<Vec3, Quat>> path;
    while (std::getline(ifs, line)) {
        auto pos_p = line.find("\"pos\": [");
        if (pos_p == std::string::npos) continue;
        Vec3 p; Quat q;
        if (sscanf(line.c_str() + pos_p, "\"pos\": [%f, %f, %f], \"quat\": [%f, %f, %f, %f]",
                   &p.x, &p.y, &p.z, &q.w, &q.x, &q.y, &q.z) == 7) {
            path.push_back({p, q_norm(q)});
        }
    }
    printf("Loaded %zu waypoints (%zu moves). Checking exact 89,448-voxel continuous clearance...\n",
           path.size(), path.size() - 1);

    std::vector<float> eclr(path.size() - 1);
    for (size_t k = 0; k + 1 < path.size(); ++k) {
        eclr[k] = step_exact(path[k].first, path[k].second, path[k+1].first, path[k+1].second, -10.0f);
    }
    printf("Before polish: exact 89,448-voxel min clearance = %.5f m\n",
           *std::min_element(eclr.begin(), eclr.end()));
    fflush(stdout);

    // Hill-climb polish on ALL 89,448 voxels!
    std::mt19937 rng(2026);
    std::normal_distribution<float> g(0.0f, 1.0f);
    for (int pass = 0; pass < 20; ++pass) {
        float rp = (pass < 10) ? 0.004f : 0.0012f;
        float rq = (pass < 10) ? 0.006f : 0.0020f;
        for (size_t i = 1; i + 1 < path.size(); ++i) {
            float cur = std::min(eclr[i-1], eclr[i]);
            if (cur >= 0.018f) continue;
            for (int tr = 0; tr < 14; ++tr) {
                Vec3 tp = path[i].first + Vec3{g(rng)*rp, g(rng)*rp, g(rng)*rp};
                Quat tq = q_norm(q_mul(q_exp({g(rng)*rq, g(rng)*rq, g(rng)*rq}), path[i].second));
                float n1 = step_exact(path[i-1].first, path[i-1].second, tp, tq, cur + 2e-5f);
                if (n1 > cur + 2e-5f) {
                    float n2 = step_exact(tp, tq, path[i+1].first, path[i+1].second, cur + 2e-5f);
                    if (std::min(n1, n2) > cur + 2e-5f) {
                        path[i] = {tp, tq};
                        eclr[i-1] = n1; eclr[i] = n2;
                        cur = std::min(n1, n2);
                    }
                }
            }
        }
    }

    float final_mc = *std::min_element(eclr.begin(), eclr.end());
    printf("After 89,448-voxel polish: exact min continuous clearance = %.5f m!\n", final_mc);
    for (size_t k = 0; k < eclr.size(); ++k) {
        if (eclr[k] < 0.015f)
            printf("  Tight step %2zu: lin=%.4f, ang=%.4f, exact_clr=%.5f m\n",
                   k + 1, norm(path[k+1].first - path[k].first), q_angle(path[k].second, path[k+1].second), eclr[k]);
    }

    FILE* fout = fopen("/tmp/opencode/waypoints_polished.json", "w");
    fprintf(fout, "{\n  \"min_clearance_m\": %.6f,\n  \"waypoints\": [\n", final_mc);
    for (size_t i = 0; i < path.size(); ++i) {
        const auto& wp = path[i];
        fprintf(fout, "    {\"pos\": [%.6f, %.6f, %.6f], \"quat\": [%.7f, %.7f, %.7f, %.7f]}%s\n",
                wp.first.x, wp.first.y, wp.first.z,
                wp.second.w, wp.second.x, wp.second.y, wp.second.z,
                (i + 1 < path.size()) ? "," : "");
    }
    fprintf(fout, "  ]\n}\n");
    fclose(fout);
    return 0;
}

arguments.newString:
float final_mc = *std::min_element(eclr.begin(), eclr.end());
printf("After 89,448-voxel polish: exact min continuous clearance = %.5f m!\n", final_mc);

// Exact 89,448-voxel clearance-preserving shortcutting (single-step replacements [i..j] -> 1 step)!
bool merged = true;
while (merged) {
    merged = false;
    for (size_t i = 0; i + 2 < path.size() && !merged; ++i) {
        for (size_t j = path.size() - 1; j >= i + 2; --j) {
            float lin = norm(path[j].first - path[i].first);
            float ang = q_angle(path[i].second, path[j].second);
            float orig_min = 10.0f;
            for (size_t k = i; k < j; ++k) orig_min = std::min(orig_min, eclr[k]);
            // Keep cautious cap (0.065m, 0.13rad) in tight zone, (0.094m, 0.184rad) in open zone
            float max_l = (orig_min < 0.015f) ? 0.065f : 0.094f;
            float max_a = (orig_min < 0.015f) ? 0.130f : 0.184f;
            if (lin > max_l || ang > max_a) continue;
            float req = std::min(0.018f, orig_min - 0.0001f);
            req = std::max(req, final_mc - 0.00005f);
            float c = step_exact(path[i].first, path[i].second, path[j].first, path[j].second, req);
            if (c >= req) {
                path.erase(path.begin() + i + 1, path.begin() + j);
                eclr.erase(eclr.begin() + i + 1, eclr.begin() + j);
                eclr[i] = c;
                merged = true;
                break;
            }
        }
    }
}

final_mc = *std::min_element(eclr.begin(), eclr.end());
printf("After exact 1-step shortcutting: %zu moves, exact min continuous clearance = %.5f m!\n",
       eclr.size(), final_mc);
